-- Reports (spec §6.10), code REPORT-xxxxx. org_admin inserts a report (type, format, period, targets nested in the
-- same insert) and it is generated by the event trigger render_report (backend):
--   queued -> generating (claimed with a 5-minute lease; attempts + 1) -> completed | failed (error).
--   generating -> generating: a handler that died is reclaimed after its lease (itap.claim_report).
--   queued -> failed: out of attempts at claim time (error 'max_attempts').
--   failed -> queued: itap.retry_report (org_admin).  completed | failed -> expired: retention (slice 10).
-- Status / file / summary / error / generated_at / attempts / lease are system columns (read-only in metadata,
-- not audited). Period: start_date..end_date inclusive local dates (parameters.timezone, else the organization's);
-- required except for incident reports, at most 366 days. Targets: report_facilities (none = all facilities),
-- report_segments (segment reports; none = all segments). report_metrics: computed figures, replaced on each
-- generation attempt. Reports are history: no delete for org_admin; the schedule / template going away nulls the
-- link. One scheduled report per schedule and period (reports_schedule_period_key: an idempotent cron).
CREATE TABLE itap.reports (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES itap.organizations (id) ON DELETE CASCADE,
  number bigint NOT NULL,
  code text GENERATED ALWAYS AS ('REPORT-' || lpad(number::text, 5, '0')) STORED,
  report_type text NOT NULL REFERENCES itap.report_types (value),
  title text NOT NULL,
  description text,
  parameters jsonb NOT NULL DEFAULT '{}'::jsonb,
  start_date date,
  end_date date,
  incident_id uuid,
  format text NOT NULL DEFAULT 'pdf' REFERENCES itap.report_formats (value),
  status text NOT NULL DEFAULT 'queued' REFERENCES itap.report_statuses (value),
  file_id uuid REFERENCES storage.files (id) ON DELETE SET NULL,
  summary jsonb,
  error text,
  template_id uuid,
  schedule_id uuid,
  generated_at timestamptz,
  attempts integer NOT NULL DEFAULT 0,
  lease_expires_at timestamptz,
  created_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT reports_organization_id_id_key UNIQUE (organization_id, id),
  CONSTRAINT reports_organization_id_number_key UNIQUE (organization_id, number),
  CONSTRAINT reports_organization_id_code_key UNIQUE (organization_id, code),
  CONSTRAINT reports_title_not_blank CHECK (btrim(title) <> ''),
  CONSTRAINT reports_parameters_valid CHECK (itap.valid_report_parameters(parameters)),
  CONSTRAINT reports_incident CHECK ((report_type = 'incident') = (incident_id IS NOT NULL)),
  CONSTRAINT reports_period CHECK (
    (start_date IS NULL) = (end_date IS NULL)
    AND (report_type = 'incident' OR start_date IS NOT NULL)
    AND (start_date IS NULL OR (start_date <= end_date AND end_date - start_date <= 366))),
  CONSTRAINT reports_attempts_nonnegative CHECK (attempts >= 0),
  CONSTRAINT reports_summary_object CHECK (summary IS NULL OR jsonb_typeof(summary) = 'object'),
  CONSTRAINT reports_incident_fkey FOREIGN KEY (organization_id, incident_id)
    REFERENCES itap.incidents (organization_id, id) ON DELETE NO ACTION,
  CONSTRAINT reports_template_fkey FOREIGN KEY (organization_id, template_id)
    REFERENCES itap.report_templates (organization_id, id) ON DELETE SET NULL (template_id),
  CONSTRAINT reports_schedule_fkey FOREIGN KEY (organization_id, schedule_id)
    REFERENCES itap.report_schedules (organization_id, id) ON DELETE SET NULL (schedule_id),
  CONSTRAINT reports_created_by_fkey FOREIGN KEY (organization_id, created_by)
    REFERENCES itap.organization_members (organization_id, user_id) ON DELETE NO ACTION
);
CREATE INDEX reports_organization_id_report_type_idx ON itap.reports (organization_id, report_type);
CREATE INDEX reports_organization_id_format_idx ON itap.reports (organization_id, format);
CREATE INDEX reports_organization_id_status_idx ON itap.reports (organization_id, status);
CREATE INDEX reports_organization_id_incident_id_idx ON itap.reports (organization_id, incident_id);
CREATE INDEX reports_organization_id_template_id_idx ON itap.reports (organization_id, template_id);
CREATE INDEX reports_organization_id_schedule_id_idx ON itap.reports (organization_id, schedule_id);
CREATE INDEX reports_organization_id_created_by_idx ON itap.reports (organization_id, created_by);
CREATE INDEX reports_organization_id_created_at_idx ON itap.reports (organization_id, created_at DESC);
CREATE INDEX reports_organization_id_file_id_idx ON itap.reports (organization_id, file_id);
CREATE UNIQUE INDEX reports_schedule_period_key ON itap.reports (organization_id, schedule_id, start_date, end_date)
  WHERE schedule_id IS NOT NULL;
-- Work for the cron (queued reports the trigger missed, expired leases).
CREATE INDEX reports_pending_idx ON itap.reports (updated_at) WHERE status IN ('queued', 'generating');

CREATE FUNCTION itap.report_transition_allowed(p_from text, p_to text) RETURNS boolean
LANGUAGE sql IMMUTABLE PARALLEL SAFE
SET search_path = pg_catalog
AS $$
  SELECT CASE p_from
    WHEN 'queued' THEN p_to IN ('queued', 'generating', 'failed')
    WHEN 'generating' THEN p_to IN ('generating', 'completed', 'failed')
    WHEN 'failed' THEN p_to IN ('failed', 'queued', 'expired')
    WHEN 'completed' THEN p_to IN ('completed', 'expired')
    ELSE p_to = p_from
  END;
$$;

-- Applies to every writer (trusted SQL included): status transitions; the generation columns of a queued report
-- start clean; a template must be of the report's type.
CREATE FUNCTION itap.reports_guard() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, itap
AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NOT itap.report_transition_allowed(OLD.status, NEW.status) THEN
    PERFORM itap.raise_code('report_invalid_transition');
  END IF;
  IF (TG_OP = 'INSERT' OR NEW.template_id IS DISTINCT FROM OLD.template_id) AND NEW.template_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM itap.report_templates t WHERE t.organization_id = NEW.organization_id
                     AND t.id = NEW.template_id AND t.report_type = NEW.report_type) THEN
    PERFORM itap.raise_code('report_template_type_mismatch');
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER reports_guard BEFORE INSERT OR UPDATE ON itap.reports
  FOR EACH ROW EXECUTE FUNCTION itap.reports_guard();
CREATE TRIGGER reports_number BEFORE INSERT ON itap.reports
  FOR EACH ROW EXECUTE FUNCTION itap.assign_number('report');
CREATE TRIGGER reports_check_files BEFORE INSERT OR UPDATE OF file_id ON itap.reports
  FOR EACH ROW EXECUTE FUNCTION itap.check_file_bucket('file_id');
CREATE TRIGGER reports_set_updated_at BEFORE UPDATE ON itap.reports
  FOR EACH ROW EXECUTE FUNCTION itap.set_updated_at();
CREATE TRIGGER audit AFTER INSERT OR UPDATE OR DELETE ON itap.reports
  FOR EACH ROW EXECUTE FUNCTION itap.audit_row_change(
    'ignore:status', 'ignore:file_id', 'ignore:summary', 'ignore:error', 'ignore:generated_at', 'ignore:attempts',
    'ignore:lease_expires_at');

CREATE TABLE itap.report_facilities (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES itap.organizations (id) ON DELETE CASCADE,
  report_id uuid NOT NULL,
  facility_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT report_facilities_organization_id_id_key UNIQUE (organization_id, id),
  CONSTRAINT report_facilities_report_facility_key UNIQUE (organization_id, report_id, facility_id),
  CONSTRAINT report_facilities_report_fkey FOREIGN KEY (organization_id, report_id)
    REFERENCES itap.reports (organization_id, id) ON DELETE CASCADE,
  CONSTRAINT report_facilities_facility_fkey FOREIGN KEY (organization_id, facility_id)
    REFERENCES itap.facilities (organization_id, id) ON DELETE NO ACTION
);
CREATE INDEX report_facilities_organization_id_facility_id_idx ON itap.report_facilities (organization_id, facility_id);
CREATE TRIGGER report_facilities_set_updated_at BEFORE UPDATE ON itap.report_facilities
  FOR EACH ROW EXECUTE FUNCTION itap.set_updated_at();
CREATE TRIGGER audit AFTER INSERT OR UPDATE OR DELETE ON itap.report_facilities
  FOR EACH ROW EXECUTE FUNCTION itap.audit_row_change();

CREATE TABLE itap.report_segments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES itap.organizations (id) ON DELETE CASCADE,
  report_id uuid NOT NULL,
  segment_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT report_segments_organization_id_id_key UNIQUE (organization_id, id),
  CONSTRAINT report_segments_report_segment_key UNIQUE (organization_id, report_id, segment_id),
  CONSTRAINT report_segments_report_fkey FOREIGN KEY (organization_id, report_id)
    REFERENCES itap.reports (organization_id, id) ON DELETE CASCADE,
  CONSTRAINT report_segments_segment_fkey FOREIGN KEY (organization_id, segment_id)
    REFERENCES itap.segments (organization_id, id) ON DELETE NO ACTION
);
CREATE INDEX report_segments_organization_id_segment_id_idx ON itap.report_segments (organization_id, segment_id);
CREATE TRIGGER report_segments_set_updated_at BEFORE UPDATE ON itap.report_segments
  FOR EACH ROW EXECUTE FUNCTION itap.set_updated_at();
CREATE TRIGGER audit AFTER INSERT OR UPDATE OR DELETE ON itap.report_segments
  FOR EACH ROW EXECUTE FUNCTION itap.audit_row_change();

-- Computed figures of a report (append-only per attempt; read-only). dimension: labels (names, hour), never ids.
CREATE TABLE itap.report_metrics (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES itap.organizations (id) ON DELETE CASCADE,
  report_id uuid NOT NULL,
  metric_name text NOT NULL,
  metric_type text NOT NULL REFERENCES itap.report_metric_types (value),
  value numeric NOT NULL,
  unit text,
  category text,
  dimension jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT report_metrics_organization_id_id_key UNIQUE (organization_id, id),
  CONSTRAINT report_metrics_dimension_object CHECK (jsonb_typeof(dimension) = 'object'),
  CONSTRAINT report_metrics_report_fkey FOREIGN KEY (organization_id, report_id)
    REFERENCES itap.reports (organization_id, id) ON DELETE CASCADE
);
CREATE INDEX report_metrics_organization_id_report_id_idx ON itap.report_metrics (organization_id, report_id);
CREATE INDEX report_metrics_organization_id_metric_type_idx ON itap.report_metrics (organization_id, metric_type);
